        this._justificativaGrid.setParam('origem', 2) // Choice: ('ponto', 'ORIGEM_JUSTIFICATIVA', 'Gestor de Faltas')
        this._justificativaGrid.setParam('modulo', 2)
        return this._justificativaGrid;
