    _observeJustificativaGrid: function (cfg) {
        console.log(cfg)
        if ((this.oId || cfg.oId) && this.getJustificadoField().checked) {
            this.getJustificativaGrid().enable();
            this.getJustificativaGrid().setFilterProperty('fault', cfg.oId ? cfg.oId : '', 1002, true)

            this.getJustificativaGrid().setParam('fault', cfg.oId ? cfg.oId : 0)
            this.getJustificativaGrid().setParam('employee', cfg.values ? cfg.values.servidor : 0)
            this.getJustificativaGrid().setParam('data_inicio', this._start ? this._start : 0)
            this.getJustificativaGrid().setParam('total_dias', this._days ? this._days : 0)
            this.getJustificativaGrid().setParam('data_fim', this._end ? this._end : 0)
        } else {
            this.getJustificativaGrid().disable();
            this.getJustificativaGrid().setParam('fault', 0)
            this.getJustificativaGrid().setParam('employee', 0)
        }
    },

    constructor: function(cfg) {
        rh.falta.FaltaWindow.superclass.constructor.call(this, cfg);
        this._observeJustificadoField(cfg);
    },
